<section class="panel commerce-order"><h2><?=e(t('สรุปราคาและบริการขนส่ง'))?></h2><div class="commerce-price-breakdown"><p><?=e(t('ยอดรวมสินค้า'))?> <strong><?=money($o['subtotal'])?></strong></p><p><?=e(t('ส่วนลดสินค้า'))?> <strong>− <?=money($o['product_discount']??0)?></strong></p><p><?=e(t('ส่วนลดคูปอง'))?> <strong>− <?=money($o['coupon_discount']??0)?></strong></p><p><?=e(t('ค่าจัดส่ง'))?> <strong><?=money($o['shipping_base']??$o['shipping'])?></strong></p><p><?=e(t('ส่วนลดค่าจัดส่ง'))?> <strong>− <?=money($o['shipping_discount']??0)?></strong></p><p><?=e(t('ค่าบริการ COD'))?> <strong><?=money($o['cod_fee']??0)?></strong></p><?php $tax=json_decode($o['tax_snapshot']??'{}',true)?:[];if(!empty($tax['registered'])): ?><p><?=e(t('มูลค่าก่อนภาษี'))?> <strong><?=money($o['net_before_tax'])?></strong></p><p>VAT <?=number_format($tax['rate_bps']/100,2)?>% <strong><?=money($o['vat_amount'])?></strong></p><?php endif ?><p><?=e(t('ยอดสุทธิ'))?> <strong><?=money($o['total'])?></strong></p></div><p><?=e(t('บริการขนส่งที่เลือก:'))?> <?=e($o['shipping_service_name']??'บริการมาตรฐานเดิม')?></p>
<?php $applied=json_decode($o['price_breakdown']??'[]',true)?:[];foreach($applied as $promotion): ?><p><?=e($promotion['name'])?><?=!empty($promotion['code'])?' · '.e($promotion['code']):''?> − <?=money((int)$promotion['discount']/100)?></p><?php endforeach ?>
<?php if($o['payment_method']==='PROMPTPAY'): ?><h2><?=e(t('QR PromptPay ของคำสั่งซื้อนี้'))?></h2><p><?=e(t('ชื่อผู้รับ:'))?> <?=e($o['promptpay_name'])?></p><p><?=e(t('พร้อมเพย์:'))?> <?=e($o['promptpay_recipient'])?></p><p><?=e(t('ยอด'))?> <?=money($o['total'])?></p><?php if($o['status']!=='cancelled'&&in_array($o['payment_status'],['unpaid','rejected'],true)&&cents($o['total'])>0): ?><div class="promptpay-qr" data-qr-payload="<?=e(promptpay_payload($o['promptpay_type'],$o['promptpay_recipient'],cents($o['total'])))?>" aria-label="QR PromptPay ระบุยอดคำสั่งซื้อ"></div><p><?=e(t('ตรวจชื่อผู้รับและยอดในแอปธนาคารก่อนโอน ไม่ต้องโอนซ้ำถ้าส่งหลักฐานไว้แล้ว'))?></p><?php else: ?><p><?=e(t('คำสั่งซื้อนี้ไม่ต้องชำระผ่าน QR เพิ่ม'))?></p><?php endif ?><?php endif ?></section>
